import '../../../services/auth/auth_service.dart';
import '../../../services/personal_ai/mission_mode_service.dart';
import '../../messenger/presentation/messenger_screen.dart';
class AurenMissionModeScreen extends StatefulWidget{const AurenMissionModeScreen({super.key});@override State<AurenMissionModeScreen> createState()=>_AurenMissionModeScreenState();}
class _AurenMissionModeScreenState extends State<AurenMissionModeScreen>{final a=FirebaseAurenAuthService();late Future<AurenMission> f;@override void initState(){super.initState();f=_load();}Future<AurenMission> _load()async{final u=a.currentUserId;if(u==null)throw StateError('Sign in required');return MissionModeService().build(u);} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('AUREN Mission Mode')),body:FutureBuilder<AurenMission>(future:f,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final m=s.data!;return ListView(padding:const EdgeInsets.all(20),children:[Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('المهمة الحالية',style:TextStyle(fontSize:18)),const SizedBox(height:8),Text(m.goalTitle,style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:12),Text(m.mission),const SizedBox(height:16),LinearProgressIndicator(value:m.progress/100),const SizedBox(height:8),Text('التقدم: '+m.progress.toString()+'%')])),),const SizedBox(height:12),Card(child:ListTile(title:const Text('أول خطوة'),subtitle:Text(m.firstStep))),const SizedBox(height:20),FilledButton.icon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>MessengerScreen(initialPrompt:m.firstStep))),icon:const Icon(Icons.play_arrow),label:const Text('ابدأ المهمة'))]);}));}